package com.example.data.remote

import android.content.Context
import android.util.Log
import com.example.BuildConfig
import com.example.R
import com.google.firebase.FirebaseApp
import com.google.firebase.FirebaseOptions
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore

/**
 * Centralized, thread-safe Firebase initialization and configuration resolver.
 *
 * Prefers resources generated by the Google Services plugin (from `app/google-services.json`)
 * and safely falls back to the verified project options / BuildConfig settings when
 * `google-services.json` is absent in the workspace.
 */
object FirebaseBootstrap {

    private const val TAG = "FirebaseBootstrap"
    private val initLock = Any()

    // Verified Firebase project configuration matching the existing NearGrid project
    private const val FALLBACK_APP_ID = "1:253737365034:android:858656ab161612d795dd53"
    private const val FALLBACK_PROJECT_ID = "gen-lang-client-0509703417"
    private const val FALLBACK_API_KEY = "AIzaSyBSc8bWTsIYVL8Sj7kicx9zSZLOAcLD1LA"
    private const val FALLBACK_GCM_SENDER_ID = "253737365034"
    private const val FALLBACK_STORAGE_BUCKET = "gen-lang-client-0509703417.firebasestorage.app"

    private val PLACEHOLDER_CLIENT_IDS = setOf(
        "YOUR_DEFAULT_WEB_CLIENT_ID",
        "YOUR_WEB_CLIENT_ID",
        "YOUR_OAUTH_CLIENT_ID",
        "DEFAULT_WEB_CLIENT_ID",
        "REPLACE_ME",
        "TODO",
        "NULL",
        "NONE"
    )

    private val GOOGLE_OAUTH_CLIENT_ID_REGEX =
        Regex("^[0-9]+-[A-Za-z0-9_\\-]+\\.apps\\.googleusercontent\\.com$")

    /**
     * Ensures a default [FirebaseApp] exists in this process.
     *
     * Note: `FirebaseApp.initializeApp(Context)` returns `null` (without throwing) when
     * `google-services.json` resources are missing. We explicitly check the return value
     * before applying the verified project fallback options.
     */
    fun ensureInitialized(context: Context): FirebaseApp? {
        val appContext = context.applicationContext ?: context
        synchronized(initLock) {
            val existing = runCatching { FirebaseApp.getApps(appContext).firstOrNull() }.getOrNull()
            if (existing != null) {
                return existing
            }

            val autoInitialized = try {
                FirebaseApp.initializeApp(appContext)
            } catch (e: Exception) {
                Log.w(TAG, "Auto FirebaseApp initialization threw an exception", e)
                null
            }

            if (autoInitialized != null) {
                Log.d(TAG, "FirebaseApp initialized from Google Services resources")
                return autoInitialized
            }

            val existingAfterAuto = runCatching { FirebaseApp.getApps(appContext).firstOrNull() }.getOrNull()
            if (existingAfterAuto != null) {
                return existingAfterAuto
            }

            Log.w(
                TAG,
                "google-services.json resources missing; initializing FirebaseApp with project fallback options"
            )
            return try {
                val options = FirebaseOptions.Builder()
                    .setApplicationId(FALLBACK_APP_ID)
                    .setProjectId(FALLBACK_PROJECT_ID)
                    .setApiKey(FALLBACK_API_KEY)
                    .setGcmSenderId(FALLBACK_GCM_SENDER_ID)
                    .setStorageBucket(FALLBACK_STORAGE_BUCKET)
                    .build()
                FirebaseApp.initializeApp(appContext, options)
                    ?: runCatching { FirebaseApp.getApps(appContext).firstOrNull() }.getOrNull()
            } catch (e: IllegalStateException) {
                // Another initialization path may have registered the default app concurrently
                runCatching { FirebaseApp.getApps(appContext).firstOrNull() }.getOrNull()
            } catch (e: Exception) {
                Log.e(TAG, "Fatal error initializing FirebaseApp", e)
                null
            }
        }
    }

    fun getAuth(context: Context): FirebaseAuth? {
        val app = ensureInitialized(context) ?: return null
        return try {
            FirebaseAuth.getInstance(app)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to obtain FirebaseAuth instance", e)
            null
        }
    }

    fun getFirestore(context: Context): FirebaseFirestore? {
        val appContext = context.applicationContext ?: context
        val app = ensureInitialized(appContext) ?: return null
        val databaseId = readDatabaseId(appContext)

        if (databaseId.isBlank() || databaseId == "(default)") {
            Log.e(
                TAG,
                "Named Firestore database ID (R.string.firestore_database_id) is missing or invalid; refusing (default) fallback."
            )
            return null
        }

        return try {
            FirebaseFirestore.getInstance(app, databaseId)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to obtain named FirebaseFirestore instance ($databaseId)", e)
            null
        }
    }

    fun readDatabaseId(context: Context): String {
        return try {
            context.getString(R.string.firestore_database_id).trim()
        } catch (e: Exception) {
            Log.w(TAG, "firestore_database_id string resource unavailable", e)
            ""
        }
    }

    /**
     * Returns true when `google-services.json` was processed during build and generated
     * the `google_app_id` string resource.
     */
    fun hasGoogleServicesResourceConfig(context: Context): Boolean {
        return try {
            val resId = context.resources.getIdentifier("google_app_id", "string", context.packageName)
            resId != 0 && context.getString(resId).isNotBlank()
        } catch (e: Exception) {
            false
        }
    }

    /**
     * Resolves the OAuth 2.0 Web Client ID for Credential Manager / Google Sign-In.
     *
     * Priority:
     * 1. `R.string.default_web_client_id` generated from `google-services.json`
     * 2. `BuildConfig.DEFAULT_WEB_CLIENT_ID` populated from `.env` / `.env.example`
     */
    fun resolveWebClientId(context: Context): String? {
        val fromResources = try {
            context.getString(R.string.default_web_client_id).trim()
        } catch (_: Exception) {
            null
        }
        if (isValidWebClientId(fromResources)) {
            return fromResources!!
        }

        val fromBuildConfig = runCatching { BuildConfig.DEFAULT_WEB_CLIENT_ID }.getOrNull()
        if (isValidWebClientId(fromBuildConfig)) {
            return fromBuildConfig!!.trim()
        }

        return null
    }

    fun isValidWebClientId(candidate: String?): Boolean {
        val trimmed = candidate?.trim() ?: return false
        if (trimmed.isEmpty()) return false
        val upper = trimmed.uppercase()
        if (PLACEHOLDER_CLIENT_IDS.any { upper == it || upper.contains("YOUR_") || upper.contains("PLACEHOLDER") }) {
            return false
        }
        return GOOGLE_OAUTH_CLIENT_ID_REGEX.matches(trimmed)
    }
}
